 await check("Disable configuration uses explicit booleans and CAS only",async()=>{const h=harness();await h.api.load();await h.find("Disable QQQ workflow").fire("click");const call=h.writes()[0];assert.equal(call.path,"/qqq/config");assert.equal(call.options.method,"PUT");assert.deepEqual(copy(call.options.body),{expected_revision:7,enabled:false,paused:false});});
 await check("Local pause uses distinct workflow control",async()=>{const h=harness();await h.api.load();await h.find("Pause QQQ workflow").fire("click");assert.deepEqual(copy(h.writes()[0].options.body),{expected_revision:7,enabled:true,paused:true});});
