 await check("Stale data blocks starting paper and states the hold",async()=>{const h=harness();h.response.quality.fresh_now=false;await h.api.load();assert(h.find("Start $10,000 simulated account").disabled);await h.api.startPaper();assert.equal(h.writes().length,0);assert.match(h.body.textContent,/unavailable or stale/);});
