 await check("Starting paper confirms simulated money and sends exact fields",async()=>{const h=harness();await h.api.load();await h.api.startPaper();const call=h.writes()[0];assert.equal(call.path,"/qqq/paper");assert.equal(call.options.body.replace,false);assert.equal(call.options.body.acknowledge_simulated,true);assert.equal(call.options.body.expected_revision,7);assert.match(h.confirmations[0][1],/not your budget or a deposit/);assert.match(h.toasts[0],/No money deposited/);});
 await check("Replacement explicitly retains old simulation and uses replace true",async()=>{const h=harness();h.response.paper=account();await h.api.load();await h.api.startPaper();assert.equal(h.writes()[0].options.body.replace,true);assert.match(h.confirmations[0][1],/old simulated account and its losses remain retained/);});
