 await check("Every new run uses one unique request id and no automatic repeat",async()=>{const h=harness();await h.api.load();await h.api.run("refresh");await h.api.run("backtest");assert.equal(h.writes().length,2);assert.notEqual(h.writes()[0].options.body.request_id,h.writes()[1].options.body.request_id);assert.match(h.writes()[0].options.body.request_id,/^qqq-ui-/);});
