 await check("Hold acknowledgement references exact inspected old request",async()=>{const h=harness();h.response.hold={request_id:"failed-one",status:"failed"};await h.api.load();await h.api.acknowledge();assert.deepEqual(copy(h.writes()[0].options.body),{request_id:"failed-one",expected_revision:7});assert.equal(h.writes()[0].path,"/qqq/acknowledge");assert.match(h.confirmations[0][1],/not adopted, deleted or replayed/);});
 await check("Cancelled hold acknowledgement keeps the failure held",async()=>{const h=harness();h.response.hold={request_id:"failed-one",status:"failed"};h.confirmHandler=()=>false;await h.api.load();await h.api.acknowledge();assert.equal(h.writes().length,0);});
 await check("Stale revision blocks another write until refreshed",async()=>{const h=harness();await h.api.load();h.handler=(p,o)=>{if(o)throw Object.assign(new Error("changed"),{status:409});return h.defaultReply(p,o);};await h.api.run("backtest");await h.api.run("refresh");assert.equal(h.writes().length,1);assert.match(h.body.textContent,/saved revision changed/);h.handler=null;await h.api.load();await h.api.run("refresh");assert.equal(h.writes().length,2);});
 await check("Uncertain transport never repeats mutation automatically",async()=>{const h=harness();await h.api.load();h.handler=(p,o)=>{if(o)throw new Error("connection interrupted");return h.defaultReply(p,o);};await h.api.run("refresh");await h.api.run("refresh");assert.equal(h.writes().length,1);assert.match(h.body.textContent,/No action is retried automatically/);assert(h.find("I inspected the saved QQQ records"));});
 await check("Owner inspection clears local uncertainty without replaying old id",async()=>{const h=harness();await h.api.load();h.handler=(p,o)=>{if(o)throw new Error("timeout");return h.defaultReply(p,o);};await h.api.run("refresh");const old=h.writes()[0].options.body.request_id;h.handler=null;await h.find("I inspected the saved QQQ records").fire("click");assert.equal(h.writes().length,1);await h.api.run("refresh");assert.equal(h.writes().length,2);assert.notEqual(old,h.writes()[1].options.body.request_id);});
 await check("Missing mutation receipt becomes uncertain rather than successful",async()=>{const h=harness();await h.api.load();h.handler=(p,o)=>o?{}:h.defaultReply(p,o);await h.api.run("backtest");assert.equal(h.toasts.length,0);assert.match(h.body.textContent,/expected saved receipt/);await h.api.run("refresh");assert.equal(h.writes().length,1);});
 await check("Status read failure keeps writes blocked",async()=>{const h=harness();await h.api.load();h.handler=()=>{throw new Error("not readable");};await h.api.load();assert(h.find("Update market data").disabled);assert.match(h.body.textContent,/not readable/);});
 await check("Authentication change discards a pending read",async()=>{const h=harness(),pending=defer();h.handler=()=>pending.promise;const load=h.api.load();h.app.state.token="different-key";pending.resolve(board());await load;assert.equal(h.body.textContent,"");assert.equal(h.writes().length,0);});
 await check("Lock clears sensitive status and ignores in-flight read",async()=>{const h=harness();await h.api.load();const pending=defer();h.handler=()=>pending.promise;const load=h.api.load();h.api.locked();pending.resolve(board());await load;assert.equal(h.body.textContent,"");});
